skills.move_to:
def move_to(arm, position, finger=None, jaw=None, steps=6, joint_step=0.08):
    args = {'arm':arm, 'position':position, 'steps':steps, 'joint_step':joint_step}
    if finger is not None:
        args['finger_direction'] = finger
        args['jaw_direction'] = jaw
    return tool('move_tcp', args)

skills.test_lift:
def test_lift(arm, height=0.06, steps=5):
    current = get_observation()
    tcp = current['tools']['public_robot_geometry']['tcp_world'][arm]
    position = [tcp[0][3], tcp[1][3], tcp[2][3] + height]
    return move_to(arm, position, steps=steps)

skills.diagonal_pregrasp:
def diagonal_pregrasp(arm, body_axis, directions, clearance=0.06, rise=0.035, steps=6):
    for lateral, forward, downward in directions:
        finger = [lateral, forward, downward]
        jaw = [-forward, lateral, 0.0]
        position = [body_axis[0]-clearance*lateral, body_axis[1]-clearance*forward, body_axis[2]+rise]
        before = get_observation()['step']
        print('Offset pregrasp hypothesis', arm, position, finger)
        try:
            print(move_to(arm, position, finger, jaw, steps))
            return True
        except RuntimeError as error:
            print(error)
            if get_observation()['step'] != before:
                print('Partial motion: inspect current RGB before recovery')
                return False
    return False

skills.receiver_acquire:
def receiver_acquire(arm, target, orientations, steps=5):
    for finger, jaw in orientations:
        before = get_observation()['step']
        print('Receiver local orientation attempt', finger, 'at lower-body hypothesis', target)
        try:
            print(move_to(arm, target, finger, jaw, steps=steps))
        except RuntimeError as error:
            print(error)
            if get_observation()['step'] != before:
                print('Partial motion; stop for current RGB review, donor remains closed')
                return False
            continue
        print(tool('gripper', {'arm':arm, 'value':0.0, 'steps':8}))
        print('Inspect receiver support before any donor release')
        return True
    return False

skills.retreat_tcp:
def retreat_tcp(arm, distance=0.12, steps=5, max_rise=None):
    obs = get_observation()
    matrix = obs['tools']['public_robot_geometry']['tcp_world'][arm]
    target = [matrix[i][3] - distance * matrix[i][0] for i in range(3)]
    if max_rise is not None:
        target[2] = min(target[2], matrix[2][3] + max_rise)
    return move_to(arm, target, steps=steps)

