skills.staged_receiver:
def staged_receiver(arm, target, finger, jaw, backoff=0.13):
    staging = [target[i] - backoff*finger[i] for i in range(3)]
    staging[2] = target[2]
    print('Receiver staging away from exposed lower body:', staging)
    before = get_observation()['step']
    try:
        print(move_to(arm, staging, finger, jaw, steps=5, joint_step=0.12)['result'])
    except RuntimeError as error:
        print(error)
        print('Staging failed; elapsed actions:', get_observation()['step']-before)
        return False
    return receiver_acquire(arm, target, [(finger,jaw)], steps=5)

