skills.bind_body_hypothesis:
def bind_body_hypothesis(arm, points):
    current = get_observation()
    matrix = current['tools']['public_robot_geometry']['tcp_world'][arm]
    local = {}
    for name, point in points.items():
        local[name] = [sum(matrix[j][i]*(point[j]-matrix[j][3]) for j in range(3)) for i in range(3)]
    return {'arm':arm, 'local':local, 'bound_step':current['step'], 'status':'provisional rigid retention hypothesis'}

skills.predict_body_hypothesis:
def predict_body_hypothesis(body):
    matrix = get_observation()['tools']['public_robot_geometry']['tcp_world'][body['arm']]
    return [{'name':name, 'position':[matrix[i][3]+sum(matrix[i][j]*point[j] for j in range(3)) for i in range(3)]} for name, point in body['local'].items()]

skills.move_body_center:
def move_body_center(body, center_name, target, steps=5):
